/* Reset & Universal Overrides */

* {
box-shadow: none !important;
}

/* Modal Container Base - Mobile Default (< 768px): Floating at bottom */
.install-app-modal {
position: fixed;
z-index: 9999;
width: 320px;
max-width: calc(100vw - 1em);
bottom: 0.5em;
left: 0.5em;
right: 0.5em;
top: auto;
margin-left: auto;
margin-right: auto;
transition: opacity 0.25s ease-in-out, transform 0.25s ease-in-out;

}

.install-app-modal.hidden-prompt {
opacity: 0;
pointer-events: none;
transform: translateY(20px);
}

@media (min-width: 768px) and (max-width: 1023px) {
.install-app-modal {
bottom: 0.5em;
right: 0.5em;
left: auto;
top: auto;
margin-left: 0;
margin-right: 0;
}
}

@media (min-width: 1024px) {
.install-app-modal {
top: 0.5em;
right: 0.5em;
left: auto;
bottom: auto;
margin-left: 0;
margin-right: 0;
}
}

.install-btn-accent {
background-color: var(--theme-accent, #22c55e);
}

.install-btn-accent:hover {
filter: brightness(1.1);
}

.install-btn-accent:active {
transform: scale(0.98);
}

if ('serviceWorker' in navigator) {
    window.addEventListener('load', () => {
        navigator.serviceWorker.register('sw.js')
            .catch(err => console.log('SW registration failed:', err));
    });
}

let deferredPrompt = null;

function injectPWAModal() {
    if (document.getElementById('installModal')) return;

    const modalWrapper = document.createElement('div');
    modalWrapper.innerHTML = `
      <div 
        id="installModal"
        aria-color="#22c55e"
        role="dialog"
        aria-labelledby="modalTitle"
        aria-describedby="modalDesc"
        class="install-app-modal hidden-prompt bg-[#181824] border border-slate-800 rounded-3xl overflow-hidden flex flex-col"
      >
        <div class="w-full h-32 bg-slate-900 overflow-hidden flex items-center justify-center relative">
          <img 
            src="./1000760180.png" 
            alt="App Preview Header"
            class="w-full h-full object-cover object-center pointer-events-none select-none"
            onerror="this.src='https://placehold.co/600x300/181824/22c55e?text=Install+App'"
          />
        </div>

        <div class="p-6 text-center flex flex-col items-center">
          <h3 id="modalTitle" class="text-xl font-bold text-white mb-2 tracking-tight">
            Install EduRise
          </h3>

          <p id="modalDesc" class="text-xs text-slate-400 leading-relaxed mb-6 px-1">
            Supercharge your experience with quick desktop access, offline capabilities, instant push notifications, and seamless performance!
          </p>

          <div class="w-full space-y-2">
            <button 
              id="installBtn"
              type="button" 
              class="install-btn-accent w-full py-3 px-4 rounded-xl text-sm font-semibold text-white transition duration-200"
            >
              Install App
            </button>

            <button 
              id="cancelBtn"
              type="button" 
              class="w-full py-2 text-xs font-medium text-slate-400 hover:text-slate-200 transition duration-150"
            >
              Cancel
            </button>
          </div>
        </div>
      </div>
    `;
    document.body.appendChild(modalWrapper.firstElementChild);

    applyAriaColor();
    setupEventListeners();
}

function applyAriaColor() {
    const modal = document.getElementById('installModal');
    if (!modal) return;
    const themeColor = modal.getAttribute('aria-color') || '#7c5cfc';
    modal.style.setProperty('--theme-accent', themeColor);
}

function setupEventListeners() {
    const installBtn = document.getElementById('installBtn');
    const cancelBtn = document.getElementById('cancelBtn');
    const modal = document.getElementById('installModal');

    if (installBtn) {
        installBtn.addEventListener('click', async () => {
            if (!deferredPrompt) {
                if (modal) modal.classList.add('hidden-prompt');
                return;
            }
            deferredPrompt.prompt();
            const { outcome } = await deferredPrompt.userChoice;
            if (outcome === 'accepted') {
                if (modal) modal.classList.add('hidden-prompt');
            }
            deferredPrompt = null;
        });
    }

    if (cancelBtn) {
        cancelBtn.addEventListener('click', () => {
            if (modal) modal.classList.add('hidden-prompt');
        });
    }
}

window.addEventListener('beforeinstallprompt', (e) => {
    e.preventDefault();
    deferredPrompt = e;
    const modal = document.getElementById('installModal');
    if (modal) {
        modal.classList.remove('hidden-prompt');
    }
});

if (document.readyState === 'loading') {
    window.addEventListener('DOMContentLoaded', injectPWAModal);
} else {
    injectPWAModal();
}

const CACHE_NAME = 'edurise-pwa-v1';
const ASSETS = [
    './',
    './index.html',
    './view.html',
    './create_course.html',
    './1000760180.png',
    './pwa.css',
    './pwa.js',
    './manifest.json'
];

self.addEventListener('install', (event) => {
    event.waitUntil(
        caches.open(CACHE_NAME).then((cache) => cache.addAll(ASSETS))
    );
    self.skipWaiting();
});

self.addEventListener('activate', (event) => {
    event.waitUntil(
        caches.keys().then((keys) => {
            return Promise.all(
                keys.filter((key) => key !== CACHE_NAME).map((key) => caches.delete(key))
            );
        })
    );
    self.clients.claim();
});

self.addEventListener('fetch', (event) => {
    event.respondWith(
        caches.match(event.request).then((cachedResponse) => {
            return cachedResponse || fetch(event.request);
        })
    );
});

